func photoAlbumAudienceError(errors validation.FieldErrors) string {
	if errors["audience"] != "" {
		return errors["audience"]
	}
	if errors["programme_id"] != "" {
		return errors["programme_id"]
	}
	return errors["team_id"]
}
func photoAlbumListTitle(management bool) string {
	if management {
		return "Todos os álbuns"
	}
	return "Os meus álbuns"
}
func photoAlbumListDescription(management bool) string {
	if management {
		return "Álbuns abertos e arquivados, sempre limitados aos destinatários definidos."
	}
	return "A visibilidade acompanha as suas inscrições e relações de tutela atuais."
}
func photoAlbumEmptyText(management bool) string {
	if management {
		return "Crie o primeiro álbum para um programa ou equipa."
	}
	return "Não existem álbuns abertos para os seus programas ou equipas."
}
func photoAlbumStatusLabel(status string) string {
	if status == "ARCHIVED" {
		return "Arquivado"
	}
	return "Aberto"
}
func photoAlbumStatusTone(status string) string {
	if status == "ARCHIVED" {
		return "neutral"
	}
	return "success"
}
func photoAlbumDetailURL(item PhotoAlbumItem, management bool) string {
	if management {
		return "/admin/albuns/" + item.ID
	}
	return "/albuns/" + item.ID
}
func photoAlbumArchiveURL(id string) string { return "/admin/albuns/" + id + "/arquivar" }
func photoAlbumIndexURL(management bool) string {
	if management {
		return "/admin/albuns"
	}
	return "/albuns"
}
func photoAlbumArea(management bool) string {
	if management {
		return "Moderação"
	}
	return "Atividade"
}
func photoAlbumAuditLabel(action string) string {
	if action == "ARCHIVED" {
		return "Álbum arquivado"
	}
	return "Álbum criado"
}

